import React, { useState, useEffect } from 'react';
import { 
  Tabs, Tab, Box, Typography, Paper, TextField, Button, 
  Select, MenuItem, FormControl, InputLabel, Table, TableBody, 
  TableCell, TableContainer, TableHead, TableRow 
} from '@mui/material';
import { Add as AddIcon } from '@mui/icons-material';
import { 
  getIncomeCategories, addIncomeCategory, getIncome, addIncome,
  getExpenseCategories, addExpenseCategory, getExpenses, addExpense,
  getFinancialSummary 
} from '../services/financeService';

const FinanceManager = () => {
  const [tabValue, setTabValue] = useState('income');
  const [incomeCategories, setIncomeCategories] = useState([]);
  const [expenseCategories, setExpenseCategories] = useState([]);
  const [income, setIncome] = useState([]);
  const [expenses, setExpenses] = useState([]);
  const [summary, setSummary] = useState(null);
  const [newCategory, setNewCategory] = useState({ type: '', name: '' });
  const [showNewCategory, setShowNewCategory] = useState(false);
  const [formData, setFormData] = useState({
    category: '',
    amount: '',
    description: ''
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [incCats, expCats, inc, exp, summ] = await Promise.all([
        getIncomeCategories(),
        getExpenseCategories(),
        getIncome(),
        getExpenses(),
        getFinancialSummary()
      ]);
      setIncomeCategories(incCats);
      setExpenseCategories(expCats);
      setIncome(inc);
      setExpenses(exp);
      setSummary(summ);
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  const handleCategoryChange = (e) => {
    const { name, value } = e.target;
    setNewCategory(prev => ({ ...prev, [name]: value }));
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleAddCategory = async () => {
    try {
      if (newCategory.type === 'income') {
        await addIncomeCategory({ name: newCategory.name });
      } else {
        await addExpenseCategory({ name: newCategory.name });
      }
      fetchData();
      setNewCategory({ type: '', name: '' });
      setShowNewCategory(false);
    } catch (error) {
      console.error('Error adding category:', error);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (tabValue === 'income') {
        await addIncome(formData);
      } else {
        await addExpense(formData);
      }
      fetchData();
      setFormData({
        category: '',
        amount: '',
        description: ''
      });
    } catch (error) {
      console.error('Error adding transaction:', error);
    }
  };

  return (
    <div>
      <Paper elevation={3} sx={{ p: 3, mb: 3 }}>
        <Typography variant="h6" gutterBottom>Financial Summary</Typography>
        {summary ? (
          <Box sx={{ display: 'flex', gap: 3 }}>
            <Box>
              <Typography>Total Income:</Typography>
              <Typography variant="h5" color="success.main">
                ${summary.totalIncome.toFixed(2)}
              </Typography>
            </Box>
            <Box>
              <Typography>Total Expenses:</Typography>
              <Typography variant="h5" color="error.main">
                ${summary.totalExpenses.toFixed(2)}
              </Typography>
            </Box>
            <Box>
              <Typography>Net Profit/Loss:</Typography>
              <Typography variant="h5" color={summary.netProfit >= 0 ? 'success.main' : 'error.main'}>
                ${summary.netProfit.toFixed(2)}
              </Typography>
            </Box>
          </Box>
        ) : (
          <Typography>Loading...</Typography>
        )}
      </Paper>

      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={tabValue} onChange={handleTabChange}>
          <Tab label="Income" value="income" />
          <Tab label="Expense" value="expense" />
        </Tabs>
      </Box>

      {tabValue === 'income' ? (
        <>
          <Paper elevation={3} sx={{ p: 3, mb: 3 }}>
            <Typography variant="h6" gutterBottom>Add Income</Typography>
            <form onSubmit={handleSubmit}>
              <FormControl fullWidth margin="normal">
                <InputLabel>Category</InputLabel>
                <Select
                  name="category"
                  value={formData.category}
                  onChange={handleFormChange}
                  required
                >
                  {incomeCategories.map(cat => (
                    <MenuItem key={cat._id} value={cat._id}>{cat.name}</MenuItem>
                  ))}
                </Select>
              </FormControl>
              <Button 
                onClick={() => setShowNewCategory(true)}
                startIcon={<AddIcon />}
                sx={{ mb: 2 }}
              >
                Add New Category
              </Button>
              
              {showNewCategory && (
                <Box sx={{ display: 'flex', gap: 2, mb: 2 }}>
                  <TextField
                    label="New Category Name"
                    name="name"
                    value={newCategory.name}
                    onChange={handleCategoryChange}
                    fullWidth
                  />
                  <Button 
                    onClick={handleAddCategory}
                    variant="contained"
                    disabled={!newCategory.name}
                  >
                    Save
                  </Button>
                  <Button 
                    onClick={() => setShowNewCategory(false)}
                    variant="outlined"
                  >
                    Cancel
                  </Button>
                </Box>
              )}
              
              <TextField
                label="Amount"
                name="amount"
                type="number"
                value={formData.amount}
                onChange={handleFormChange}
                fullWidth
                margin="normal"
                required
              />
              <TextField
                label="Description"
                name="description"
                value={formData.description}
                onChange={handleFormChange}
                fullWidth
                margin="normal"
                multiline
                rows={3}
              />
              <Button 
                type="submit" 
                variant="contained" 
                startIcon={<AddIcon />}
                sx={{ mt: 2 }}
              >
                Add Income
              </Button>
            </form>
          </Paper>

          <Paper elevation={3} sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>Income Transactions</Typography>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Date</TableCell>
                    <TableCell>Category</TableCell>
                    <TableCell>Amount</TableCell>
                    <TableCell>Description</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {income.map(item => (
                    <TableRow key={item._id}>
                      <TableCell>{new Date(item.date).toLocaleDateString()}</TableCell>
                      <TableCell>{item.category.name}</TableCell>
                      <TableCell>${item.amount.toFixed(2)}</TableCell>
                      <TableCell>{item.description}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </>
      ) : (
        <>
          <Paper elevation={3} sx={{ p: 3, mb: 3 }}>
            <Typography variant="h6" gutterBottom>Add Expense</Typography>
            <form onSubmit={handleSubmit}>
              <FormControl fullWidth margin="normal">
                <InputLabel>Category</InputLabel>
                <Select
                  name="category"
                  value={formData.category}
                  onChange={handleFormChange}
                  required
                >
                  {expenseCategories.map(cat => (
                    <MenuItem key={cat._id} value={cat._id}>{cat.name}</MenuItem>
                  ))}
                </Select>
              </FormControl>
              <Button 
                onClick={() => setShowNewCategory(true)}
                startIcon={<AddIcon />}
                sx={{ mb: 2 }}
              >
                Add New Category
              </Button>
              
              {showNewCategory && (
                <Box sx={{ display: 'flex', gap: 2, mb: 2 }}>
                  <TextField
                    label="New Category Name"
                    name="name"
                    value={newCategory.name}
                    onChange={handleCategoryChange}
                    fullWidth
                  />
                  <Button 
                    onClick={handleAddCategory}
                    variant="contained"
                    disabled={!newCategory.name}
                  >
                    Save
                  </Button>
                  <Button 
                    onClick={() => setShowNewCategory(false)}
                    variant="outlined"
                  >
                    Cancel
                  </Button>
                </Box>
              )}
              
              <TextField
                label="Amount"
                name="amount"
                type="number"
                value={formData.amount}
                onChange={handleFormChange}
                fullWidth
                margin="normal"
                required
              />
              <TextField
                label="Description"
                name="description"
                value={formData.description}
                onChange={handleFormChange}
                fullWidth
                margin="normal"
                multiline
                rows={3}
              />
              <Button 
                type="submit" 
                variant="contained" 
                startIcon={<AddIcon />}
                sx={{ mt: 2 }}
              >
                Add Expense
              </Button>
            </form>
          </Paper>

          <Paper elevation={3} sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>Expense Transactions</Typography>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Date</TableCell>
                    <TableCell>Category</TableCell>
                    <TableCell>Amount</TableCell>
                    <TableCell>Description</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {expenses.map(item => (
                    <TableRow key={item._id}>
                      <TableCell>{new Date(item.date).toLocaleDateString()}</TableCell>
                      <TableCell>{item.category.name}</TableCell>
                      <TableCell>${item.amount.toFixed(2)}</TableCell>
                      <TableCell>{item.description}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </>
      )}
    </div>
  );
};

export default FinanceManager;
